/**
 * Explicit overrides for products whose game-data class name doesn't match
 * any of our pattern-derived candidates. Keep this small — patterns should
 * catch most cases.
 */
const OVERRIDES: Record<string, string> = {
  Desc_RawQuartz_C: "IconDesc_QuartzResource.png",
  Desc_OreIron_C: "IconDesc_iron_new.png",
  Desc_OreCopper_C: "IconDesc_copper_new.png",
  Desc_Water_C: "LiquidWater_Pipe.png",
  Desc_LiquidOil_C: "LiquidOil_Pipe.png",
  Desc_Coal_C: "IconDesc_CoalOre.png",
  Desc_Stone_C: "Stone.png",
  Desc_Sulfur_C: "Sulfur.png",
  Desc_OreBauxite_C: "IconDesc_Bauxite.png",
  Desc_OreGold_C: "IconDesc_CateriumOre.png",
  Desc_OreUranium_C: "IconDesc_UraniumOre.png",
  Desc_NitrogenGas_C: "IconDesc_NitrogenGas.png",
  Desc_SAM_C: "IconDesc_SameOre.png",
  Desc_IronPlate_C: "IconDesc_IronPlates.png",
  Desc_IronPlateReinforced_C: "IconDesc_ReinforcedIronPlates.png",
  Desc_IronRod_C: "IconDesc_IronRods.png",
  Desc_IronScrew_C: "IconDesc_IronScrews.png",
  Desc_Cable_C: "IconDesc_Cables.png",
  Desc_ModularFrameHeavy_C: "IconDesc_ModularFrameHeavy.png",
  Desc_LiquidFuel_C: "IconDesc_LiquidFuel_Pipe.png",
  Desc_HeavyOilResidue_C: "IconDesc_LiquidHeavyOilResidue_Pipe.png",
  Desc_LiquidTurboFuel_C: "IconDesc_LiquidTurboFuel_Pipe.png",
  Desc_SulfuricAcid_C: "IconDesc_LiquidSulfuricAcid_Pipe.png",
  Desc_AluminaSolution_C: "LiquidAlumina_Pipe.png",
  Desc_AluminumIngot_C: "IconDesc_AluminiumIngot.png",
  Desc_AluminumCasing_C: "IconDesc_AluminiumCasing.png",
  Desc_AluminumScrap_C: "IconDesc_AluminiumScrap.png",
  Desc_AluminumPlate_C: "IconDesc_AluminiumSheet.png",
  Desc_NuclearFuelRod_C: "IconDesc_NuclearFuelRod.png",
  Desc_Diamond_C: "IconDesc_Diamonds.png",
  Desc_UraniumCell_C: "IconDesc_NuclearCell.png",
  Desc_ComputerSuper_C: "IconDesc_QuantumComputer.png",
  Desc_SkeletalFrame_C: "IconDesc_HubParts.png",
  Desc_GunPowder_C: "IconDesc_Gunpowder.png"
};

const stripDesc = (product: string) => product.replace(/^Desc_/, "").replace(/_C$/, "");

/**
 * Resolve a product ID to the best available icon URL.
 *
 * Tries an override table first, then a chain of naming patterns against the
 * static manifest. Returns null when nothing matches so the caller can render
 * a fallback avatar.
 */
export function resolveIconUrl(product: string): string | null {
  if (OVERRIDES[product]) return `/icons/${OVERRIDES[product]}`;
  const base = stripDesc(product);
  const stripLiquid = base.replace(/^Liquid/, "");
  const candidates = [
    `IconDesc_${base}.png`,
    `IconDesc_${base}s.png`,
    `IconDesc_${stripLiquid}.png`,
    `IconDesc_${base}_Pipe.png`,
    `${base}_Pipe.png`,
    `${stripLiquid}.png`,
    `${base}.png`
  ];
  for (const c of candidates) {
    if (ICON_MANIFEST.has(c)) return `/icons/${c}`;
  }
  return null;
}
